    ensures ({
        let points_to = res.0@;
        let points_to_raw = res.1@;

        points_to.ptr() == ptr
          && points_to.opt_value() == MemContents::Init(Node { ptr: next })

          && points_to_raw.dom() == perm.dom().difference(set_int_range(ptr as int, ptr as int + size_of::<Node>()))
          && points_to_raw.provenance() == ptr@.provenance
    }),
